def test_package_rule_agrees_with_find_spec_on_the_host_stdlib() -> None:
    """A stdlib name is a package exactly when CPython's finders say so.

    The oracle is CPython's own meta path (builtin, frozen, then the path
    finder) over the host stdlib directories only, so no checkout directory
    on sys.path can shadow a stdlib name.
    """
    stdlib = Path(sysconfig.get_path("stdlib"))
    search = [str(stdlib), str(stdlib / "lib-dynload")]
    expected = []
    for name in sorted(sys.stdlib_module_names):
        spec = (
            importlib.machinery.BuiltinImporter.find_spec(name)
            or importlib.machinery.FrozenImporter.find_spec(name)
            or importlib.machinery.PathFinder.find_spec(name, search)
        )
        if spec is not None and spec.submodule_search_locations is not None:
            expected.append(name)
    entries = [
        path.relative_to(stdlib).as_posix() + ("/" if path.is_dir() else "")
        for path in stdlib.glob("*")
    ]
    packages, _py_modules, _py_packages = gen.derive_version_data(
        sorted(sys.stdlib_module_names), entries
    )
    assert packages == tuple(expected)
    assert {"asyncio", "email", "json"} <= set(packages)


def test_lib_entries_keep_directories_and_py_files_below_stdlib_names() -> None:
    def record(kind: str, path: str) -> str:
        mode = {"tree": "040000", "blob": "100644", "commit": "160000"}[kind]
        return f"{mode} {kind} {'c' * 40}\t{path}"

    listing = "\0".join(
        [
            record("blob", "abc.py"),
            record("tree", "asyncio"),
            record("blob", "asyncio/__init__.py"),
            record("blob", "asyncio/README.rst"),
            record("tree", "test"),
            record("blob", "test/test_abc.py"),
            record("blob", "this.txt"),
        ]
    )
    assert gen._lib_entries((listing + "\0").encode(), FIXTURE_NAMES) == (
        "abc.py",
        "asyncio/",
        "asyncio/__init__.py",
    )
    with pytest.raises(ValueError, match="unsupported tree entry 'commit'"):
        gen._lib_entries(record("commit", "xml").encode(), FIXTURE_NAMES)


def test_header_lines_reproduce_the_blob_or_fail_closed() -> None:
    assert gen._header_lines(b"a\nb\n") == ("a", "b")
    for payload in (b"a\r\nb\r\n", b"a\nb"):
        with pytest.raises(ValueError, match="LF lines"):
            gen._header_lines(payload)


# --- The committed authority -----------------------------------------------


def test_committed_outputs_render_offline(monkeypatch, capsys) -> None:
    """The byte-equality gate: --check reads committed files and nothing else."""

    def no_network(*_args, **_kwargs):
        raise AssertionError("--check must not touch the network")

    class NoSubprocess:
        def __getattr__(self, name: str):
            raise AssertionError(f"--check must not start a process ({name})")

    monkeypatch.setattr(socket, "create_connection", no_network)
    monkeypatch.setattr(socket, "getaddrinfo", no_network)
    monkeypatch.setattr(socket.socket, "connect", no_network)
    monkeypatch.setattr(gen, "_git", no_network)
    monkeypatch.setattr(gen, "harness_memory_guard", NoSubprocess())

    assert gen.main(["--check"]) == 0
    assert "5 generated output(s) current" in capsys.readouterr().out


def test_committed_snapshot_covers_every_supported_pin() -> None:
    snapshots = gen.pinned_snapshots(tuple(gen.DEFAULT_PYTHONS))
    assert tuple(snapshots) == tuple(gen.DEFAULT_PYTHONS)
    for version, snapshot in snapshots.items():
        assert snapshot.tag.startswith(f"v{version}.")
        modules = gen.parse_stdlib_module_names(snapshot.header_lines)
        assert {"sys", "os", "asyncio"} <= set(modules)
        assert "asyncio/__init__.py" in snapshot.lib_entries


