def _rewrite_snapshot(path: Path, edit) -> None:
    payload = json.loads(path.read_text(encoding="utf-8"))
    edit(payload["sources"][0])
    path.write_text(json.dumps(payload, indent=2) + "\n", encoding="utf-8")


@pytest.mark.parametrize(
    ("edit", "message"),
    [
        (
            lambda row: row["lib"]["entries"].insert(1, "abc_fake.py"),
            r"Lib \(sha256\)",
        ),
        (
            lambda row: row["header"]["lines"].insert(5, '"fake",'),
            r"Python/stdlib_module_names.h \(sha256\)",
        ),
        (lambda row: row.update(revision="c" * 39), "not a full git object id"),
        (lambda row: row["lib"].pop("sha256"), "expected exactly the keys"),
    ],
)
def test_snapshot_content_that_breaks_its_receipt_fails_closed(
    fixture_authority: Path, edit, message: str
) -> None:
    _rewrite_snapshot(gen.SNAPSHOT_PATH, edit)
    with pytest.raises(ValueError, match=message):
        gen.generated_outputs()


def test_a_forged_header_receipt_still_fails_on_its_git_blob_id(
    fixture_authority: Path,
) -> None:
    def forge(row: dict) -> None:
        row["header"]["lines"].insert(5, '"fake",')
        payload = ("\n".join(row["header"]["lines"]) + "\n").encode()
        row["header"]["sha256"] = gen._sha256(payload)

    _rewrite_snapshot(gen.SNAPSHOT_PATH, forge)
    with pytest.raises(ValueError, match="git blob id"):
        gen.generated_outputs()


