@pytest.mark.parametrize(
    "failure",
    [
        "ASDL",
        "grammar",
        "fetched_missing",
        "fetched_pin",
        "prior_text",
        "prior_blob",
        "prior_role",
        "prior_duplicate",
        "prior_reordered",
        "prior_path",
        "prior_canonical",
    ],
)
def test_refresh_never_writes_partial_evidence_on_late_failure(
    fixture_authority, failure
):
    prior = _snapshot()
    prior = replace(prior, inputs=prior.inputs[:-1])
    gen.SNAPSHOT_PATH.write_text(gen.render_snapshot({"3.12": prior}), encoding="utf-8")
    if failure.startswith("prior_"):

        def corrupt(row):
            inputs = row["inputs"]
            if failure in ("prior_text", "prior_blob"):
                inputs[0]["text"] = "changed\n"
                if failure == "prior_blob":
                    inputs[0]["sha256"] = gen._sha256(b"changed\n")
            elif failure == "prior_role":
                inputs[0]["role"] = "unknown_evidence"
            elif failure == "prior_duplicate":
                inputs.insert(1, dict(inputs[0]))
            elif failure == "prior_reordered":
                inputs[:2] = reversed(inputs[:2])
            elif failure == "prior_path":
                inputs[0]["path"] = "Include/other.h"

        _rewrite_snapshot(gen.SNAPSHOT_PATH, corrupt)
        if failure == "prior_canonical":
            gen.SNAPSHOT_PATH.write_text(
                json.dumps(json.loads(gen.SNAPSHOT_PATH.read_text(encoding="utf-8"))),
                encoding="utf-8",
            )
    before = gen.SNAPSHOT_PATH.read_bytes()
    _write_pins(
        gen.PINS_PATH, {"3.12": ("v3.12.1", "a" * 40), "3.15": ("v3.15.0", "c" * 40)}
    )
    fetched_versions = []

    def fetch(pin):
        fetched_versions.append(pin.python)
        if pin.python == "3.15":
            if failure in ("ASDL", "grammar"):
                raise RuntimeError(f"missing pinned {failure} blob")
            pending = _snapshot(python=pin.python, tag=pin.tag, revision=pin.revision)
            if failure == "fetched_missing":
                return replace(pending, inputs=pending.inputs[:-1])
            return replace(pending, revision="d" * 40)
        return _snapshot()

    message = (
        "canonical form"
        if failure == "prior_canonical"
        else "evidence"
        if failure.startswith("prior_") or failure == "fetched_missing"
        else "pin"
        if failure == "fetched_pin"
        else f"missing pinned {failure}"
    )
    with pytest.raises((RuntimeError, ValueError), match=message):
        gen.refresh_sources(fetch=fetch)
    assert gen.SNAPSHOT_PATH.read_bytes() == before
    assert fetched_versions == (
        [] if failure.startswith("prior_") else ["3.12", "3.15"]
    )


@pytest.mark.parametrize(
    "before, after, prefix, suffix, old, new",
    [
        ("", "x", 0, 0, "", "x"),
        ("x", "", 0, 0, "x", ""),
        ("ab", "a界b", 1, 1, "", "界"),
        ("a界b", "ab", 1, 1, "界", ""),
        ("éαend", "éβend", 1, 3, "α", "β"),
        ("aaaaab", "baaaaa", 0, 0, "aaaaab", "baaaaa"),
    ],
)
def test_source_detail_has_exact_nonoverlapping_unicode_intervals(
    before, after, prefix, suffix, old, new
):
    detail = gen._source_change_detail(before, after)
    assert detail["common_prefix_chars"] == prefix
    assert detail["common_suffix_chars"] == suffix
    for side, text, changed in (("before", before, old), ("after", after, new)):
        row = detail[side]
        assert row == {
            "start_char": prefix,
            "end_char": len(text) - suffix,
            "total_chars": len(text),
            "changed_chars": len(changed),
            "head": changed,
            "tail": "",
            "omitted_chars": 0,
        }
    assert gen._source_change_detail(before, before) is None


def test_source_detail_bounds_repetitive_single_line_without_matching():
    # Shifted repetition defeats minimal-edit matchers; this contract deliberately
    # emits one exact interval with bounded detail, not guessed middle matches.
    before = "α" * 100_000 + "界"
    after = "界" + "α" * 100_000
    detail = gen._source_change_detail(before, after)
    assert detail["common_prefix_chars"] == detail["common_suffix_chars"] == 0
    for side in ("before", "after"):
        row = detail[side]
        assert row["changed_chars"] == row["total_chars"] == 100_001
        assert len(row["head"]) == len(row["tail"]) == 1024
        assert row["omitted_chars"] == 97_953
    assert detail["before"]["tail"].endswith("界")
    assert detail["after"]["head"].startswith("界")
    assert len(json.dumps(detail, ensure_ascii=True)) < 26_000


@pytest.mark.parametrize("mutation", ["missing", "path", "forged_hash"])
def test_grammar_evidence_is_required_and_bound_to_its_git_blob(
    fixture_authority, mutation
):
    def edit(row):
        grammar = next(item for item in row["inputs"] if item["role"] == "grammar")
        assert grammar["path"] == "Grammar/python.gram"
        if mutation == "missing":
            row["inputs"].remove(grammar)
        elif mutation == "path":
            grammar["path"] = "Parser/Python.asdl"
        else:
            import hashlib

            grammar["text"] = "signed_number: '+' NUMBER\n"
            grammar["sha256"] = hashlib.sha256(
                grammar["text"].encode("utf-8")
            ).hexdigest()

    _rewrite_snapshot(gen.SNAPSHOT_PATH, edit)
    with pytest.raises(ValueError, match="evidence"):
        gen.load_snapshot(gen.SNAPSHOT_PATH)


